                                                                                                    "script": {
                                                                                                        "apiVersion": "1.0.0",
                                                                                                        "controllerElementId": null,
                                                                                                        "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {any} params.imports\n */\nfunction evaluateProperty({\n    api\n}) {\n\n    if (api.state.entityTypeIds != '' && api.state.entityTypeIds.split(',').length>5) {\n        var route = \"list-view\";\n        var fields = {\n            \"table\": \"sn_grc_profile_type\",\n        };\n        var params = {\n            \"query\" : \"sys_idIN\"+ api.state.entityTypeIds,\n            \"listTitle\" : \"Entity types\"\n        };\n        var data = {\n            \"type\": \"link\",\n            \"label\": \"\",\n            \"icon\": \"chevron-right-outline\",\n            \"link\": {\n                \"type\": \"route\",\n                \"label\": \"Browse all\",\n                \"value\": {\n                    \"route\": route,\n                    \"fields\": fields,\n                    \"params\": params\n                },\n                \"opensWindow\": false,\n                \"configAria\": {},\n                \"download\": false\n            }\n        };\n        return data;\n    }\n\n    \n}",
                                                                                                        "scriptSysId": null,
                                                                                                        "target": null
